package com.fitnutri.backend.records.workout;
import com.fitnutri.backend.foodreference.*;
import com.fitnutri.backend.profile.*;
import com.fitnutri.backend.records.*;
import com.fitnutri.backend.support.*;
import com.fitnutri.backend.user.*;
import java.math.BigDecimal;
import java.net.*;
import java.net.http.*;
import java.time.LocalDate;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.web.server.LocalServerPort;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.*;
import tools.jackson.databind.ObjectMapper;
import static org.junit.jupiter.api.Assertions.*;
/** Actual cookie/CSRF/controller/transaction/PostgreSQL journey; no frontend/browser or official-provider claim. */
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT) @ActiveProfiles("integration-test")
class ExerciseRootHttpV2IT {
 static final TestDatabase DB=TestDatabase.create();static{Runtime.getRuntime().addShutdownHook(new Thread(DB::close));}
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){r.add("spring.datasource.url",DB::url);r.add("spring.datasource.username",DB::username);r.add("spring.datasource.password",DB::password);}
 @LocalServerPort int port;@Autowired ObjectMapper json;@Autowired UserRepository users;@Autowired JdbcTemplate jdbc;
 HttpClient client=client();
 static HttpClient client(){return HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).build();}
 HttpResponse<String> get(String path)throws Exception{return client.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+path)).GET().build(),HttpResponse.BodyHandlers.ofString());}
 String csrf()throws Exception{var response=get("/api/auth/csrf");assertEquals(200,response.statusCode());return json.readTree(response.body()).get("token").asText();}
 HttpResponse<String> post(String path,Object body)throws Exception{return write(path,"POST",body);}
 HttpResponse<String> write(String path,String method,Object body)throws Exception{return client.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+path)).header("Content-Type","application/json").header("X-CSRF-TOKEN",csrf()).method(method,HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build(),HttpResponse.BodyHandlers.ofString());}
 String registerAndLogin()throws Exception{String email="http-v2-"+UUID.randomUUID()+"@example.test";assertEquals(201,post("/api/auth/register",Map.of("email",email,"password","Synthetic123","displayName","Synthetic HTTP owner")).statusCode());assertEquals(200,post("/api/auth/login",Map.of("email",email,"password","Synthetic123")).statusCode());return email;}
 @Test void realCookieCanReviewSaveReplayReadCorrectAndDeleteWholeWorkout()throws Exception{
  String email=registerAndLogin();var owner=users.findByCanonicalEmail(email).orElseThrow();var date=LocalDate.of(2020,1,2);var setup=new CompleteOnboardingRequest(owner.getVersion(),null,"Synthetic HTTP owner",1990,true,Sex.PREFER_NOT_TO_SAY,new BigDecimal("170"),ActivityLevel.LIGHT,null,null,EnergyUnit.KJ,HealthSafetyAnswer.NO,false,"Australia/Sydney",new CompleteOnboardingRequest.InitialWeight(LocalDate.of(2020,1,1),new BigDecimal("70")));assertEquals(200,post("/api/profile/onboarding",setup).statusCode());var catalogue=WorkoutV2TestFixtures.catalogue(jdbc);
  var first=new LinkedHashMap<String,Object>();first.put("clientEntryId",UUID.randomUUID());first.put("periodKind","STRENGTH");first.put("optionId",Long.toString(catalogue.strengthOption()));first.put("durationMinutes",50);first.put("equipmentDetails",Map.of());first.put("movements",List.of(Map.of("catalogueId",catalogue.movements().getFirst().toString(),"setCount",3,"loadKg",40)));var second=new LinkedHashMap<String,Object>();second.put("clientEntryId",UUID.randomUUID());second.put("periodKind","ACTIVITY");second.put("optionId",Long.toString(catalogue.cardioOption()));second.put("durationMinutes",20);second.put("equipmentDetails",Map.of());second.put("movements",List.of());var entry=new LinkedHashMap<String,Object>();entry.put("kind","WORKOUT");entry.put("clientEntryId",UUID.randomUUID());entry.put("title","Synthetic HTTP workout");entry.put("periods",List.of(first,second));var input=new LinkedHashMap<String,Object>();input.put("recordDate",date);input.put("zone","Australia/Sydney");input.put("source","MANUAL");input.put("entry",entry);var response=post("/api/v2/exercise/preview",input);assertEquals(200,response.statusCode(),response.body());var preview=json.readTree(response.body());assertEquals(1342.366,preview.get("knownEnergyKj").asDouble());first.put("calculationFingerprint",preview.get("periods").get(0).get("calculationFingerprint").asText());second.put("calculationFingerprint",preview.get("periods").get(1).get("calculationFingerprint").asText());input.put("submissionId",UUID.randomUUID());input.put("previewFingerprint",preview.get("fingerprint").asText());jdbc.update("UPDATE weight_entry SET weight_kg=80 WHERE user_id=?",owner.getId());var changed=post("/api/v2/exercise/entries",input);assertEquals(409,changed.statusCode(),changed.body());assertEquals("CALCULATION_CHANGED",json.readTree(changed.body()).get("code").asText());assertEquals(2,json.readTree(changed.body()).get("currentPreview").get("periods").size());assertFalse(changed.body().contains("metUsed"));jdbc.update("UPDATE weight_entry SET weight_kg=70 WHERE user_id=?",owner.getId());var saved=post("/api/v2/exercise/entries",input);assertEquals(201,saved.statusCode(),saved.body());String id=json.readTree(saved.body()).get("roots").get(0).get("id").asText();assertEquals(2,json.readTree(saved.body()).get("leaves").size());assertEquals(200,post("/api/v2/exercise/entries",input).statusCode());var detail=get("/api/v2/exercise/entries/workout/"+id);assertEquals(200,detail.statusCode(),detail.body());var root=json.readTree(detail.body());assertEquals("CURRENT",root.get("dataQuality").asText());assertEquals(2,root.get("periodDetails").size());assertEquals(2,root.get("periodCount").asInt());assertEquals(Long.toString(catalogue.strengthOption()),root.get("periodDetails").get(0).get("option").get("id").asText());assertEquals(catalogue.movements().getFirst().toString(),root.get("periodDetails").get(0).get("movements").get(0).get("catalogue").get("id").asText());assertEquals("WORKOUT",root.get("input").get("kind").asText());assertFalse(root.get("input").has("originWorkoutId"),"Strict optional origin must not serialize null");assertEquals("Synthetic movement 0",root.get("periodDetails").get(0).get("movements").get(0).get("name").asText());assertTrue(detail.headers().firstValue("cache-control").orElse("").contains("no-store"));assertEquals(1,json.readTree(get("/api/v2/exercise/entries?from=2020-01-02&to=2020-01-02").body()).get("results").size());assertEquals(root,json.readTree(get("/api/v2/exercise/recent").body()).get("results").get(0));
  jdbc.update("UPDATE exercise_option SET active=false WHERE id=?",catalogue.strengthOption());entry.put("title","Corrected HTTP title");var correction=Map.of("expectedVersion",0,"recordDate",date,"zone","Australia/Sydney","entry",entry);var firstPreview=new LinkedHashMap<>(first);firstPreview.remove("calculationFingerprint");var secondPreview=new LinkedHashMap<>(second);secondPreview.remove("calculationFingerprint");var entryPreview=new LinkedHashMap<>(entry);entryPreview.put("periods",List.of(firstPreview,secondPreview));var reviewed=post("/api/v2/exercise/entries/workout/"+id+"/preview",Map.of("expectedVersion",0,"recordDate",date,"zone","Australia/Sydney","entry",entryPreview));assertEquals(200,reviewed.statusCode(),reviewed.body());assertEquals(1342.366,json.readTree(reviewed.body()).get("knownEnergyKj").asDouble());assertEquals(0,json.readTree(get("/api/v2/exercise/entries/workout/"+id).body()).get("version").asInt());var updated=write("/api/v2/exercise/entries/workout/"+id,"PUT",correction);assertEquals(200,updated.statusCode(),updated.body());assertEquals(1,json.readTree(updated.body()).get("version").asInt());assertFalse(json.readTree(updated.body()).get("periodDetails").get(0).get("selectableForNew").asBoolean());assertEquals(409,write("/api/v2/exercise/entries/workout/"+id,"PUT",correction).statusCode());assertEquals(204,write("/api/v2/exercise/entries/workout/"+id+"?expectedVersion=1","DELETE",Map.of()).statusCode());assertEquals(404,get("/api/v2/exercise/entries/workout/"+id).statusCode());entry.put("title","Synthetic HTTP workout");assertEquals(200,post("/api/v2/exercise/entries",input).statusCode());
  client=client();assertEquals(401,get("/api/v2/exercise/recent").statusCode());registerAndLogin();assertEquals(404,get("/api/v2/exercise/entries/workout/"+id+"?userId="+owner.getId()).statusCode());assertTrue(json.readTree(get("/api/v2/exercise/recent").body()).get("results").isEmpty());
 }
}
